import { Tag, Tooltip } from 'antd';

import { DIMENSION_LABEL, DQ_DIMENSION_HELP, type DqDimension } from './expectationCatalog';

/**
 * At-a-glance check badges (#1551) — the suite check-list card and the run-results table both
 * showed `expectation_type` alone, so two `monitor:freshness` checks on the same suite (one GX,
 * one Snowflake DMF) rendered identically, and a check's DQ dimension / severity thresholds were
 * invisible without opening its edit form.
 */

interface EngineVisual {
  label: string;
  color: string;
}

/**
 * Engine visual (ADR 0036) — label + Tag color for each engine DataQ currently offers. The
 * backend's `CHECK_ENGINES` also reserves `dqx`/`dataplex` (trigger-gated, not yet offered by any
 * connection); an engine outside this map falls back to a neutral color and its raw name below,
 * rather than silently matching gx or dmf's color.
 */
const ENGINE_VISUAL: Record<string, EngineVisual> = {
  gx: { label: 'Great Expectations (gx)', color: 'blue' },
  dmf: { label: 'Snowflake DMF (native)', color: 'purple' },
};

/** Full engine label (ADR 0036) — `CheckHistoryDrawer`'s Descriptions panel and the check editor's
 *  engine Select both read this, so a label change or a newly-offered engine has one place to update. */
// eslint-disable-next-line react-refresh/only-export-components -- helper + its badge belong together (SimpleList precedent)
export const ENGINE_LABEL: Record<string, string> = Object.fromEntries(
  Object.entries(ENGINE_VISUAL).map(([key, v]) => [key, v.label]),
);

/** Short engine text for a Tag or a plain-text table cell; the full name lives in the tooltip.
 *  A falsy engine (omitted, or an empty string) defaults to gx. */
// eslint-disable-next-line react-refresh/only-export-components -- helper + its badge belong together (SimpleList precedent)
export function engineShortLabel(engine?: string): string {
  return (engine || 'gx').toUpperCase();
}

/**
 * Compact engine badge. A DMF failure skews warehouse/permission issues, a GX failure skews
 * batch-resolution issues — naming the evaluator at a glance is the point (#1551).
 */
export function EngineTag({ engine }: { engine?: string }) {
  const key = engine || 'gx';
  const visual = ENGINE_VISUAL[key] ?? { label: key, color: 'default' };
  return (
    <Tooltip title={visual.label}>
      <Tag color={visual.color}>{engineShortLabel(engine)}</Tag>
    </Tooltip>
  );
}

/**
 * DQ-dimension badge (ADR 0038). `dimension` is `null`/`undefined` for an unclassified check —
 * that is a coverage gap by design and must render as an explicit state, never be hidden or
 * silently bucketed into another dimension. A value outside the closed 7-dimension vocabulary
 * (a legacy row) renders its raw text, uncolored — not a colored tag with a silently-empty
 * tooltip that looks identical to a real classification.
 */
export function DimensionTag({ dimension }: { dimension?: string | null }) {
  if (!dimension) {
    return (
      <Tooltip title="No DQ dimension set — a coverage gap (ADR 0038), not an error.">
        <Tag>Unclassified</Tag>
      </Tooltip>
    );
  }
  const label = DIMENSION_LABEL[dimension as DqDimension];
  if (!label) {
    return <Tag>{dimension}</Tag>;
  }
  return (
    <Tooltip title={DQ_DIMENSION_HELP[dimension as DqDimension]}>
      <Tag color="geekblue">{label}</Tag>
    </Tooltip>
  );
}

/**
 * Compact severity-threshold summary, e.g. "warn 5 · fail 10" — omits unset tiers and returns
 * `null` for a plain pass/fail check (every tier unset), so the caller can skip rendering it.
 */
// eslint-disable-next-line react-refresh/only-export-components -- helper + its badge belong together (SimpleList precedent)
export function formatThresholdsCompact(check: {
  warn_threshold: number | null;
  fail_threshold: number | null;
  critical_threshold: number | null;
}): string | null {
  const parts: string[] = [];
  if (check.warn_threshold !== null) parts.push(`warn ${check.warn_threshold}`);
  if (check.fail_threshold !== null) parts.push(`fail ${check.fail_threshold}`);
  if (check.critical_threshold !== null) parts.push(`critical ${check.critical_threshold}`);
  return parts.length > 0 ? parts.join(' · ') : null;
}

import { EyeInvisibleOutlined, EyeOutlined } from '@ant-design/icons';
import {
  Alert,
  App,
  Button,
  Card,
  Descriptions,
  Flex,
  Input,
  Spin,
  Tabs,
  Tag,
  Typography,
} from 'antd';
import { useState } from 'react';
import { Link } from 'react-router-dom';

import { type AdminWebhook, listAdminWebhooks, testAuthEmail } from '../api/admin';
import { PROVIDER_CALLBACK_NOUNS, PROVIDER_LABELS } from '../api/triggerBindings';
import { authMethodLabel } from '../auth/config';
import { useMe } from '../auth/useMe';
import { Forbidden } from '../components/Forbidden';
import { PageError } from '../components/feedback/PageError';
import { Page } from '../components/layout/Page';
import { useAsyncAction } from '../hooks/useAsyncAction';
import { useAsyncData } from '../hooks/useAsyncData';

/** Workspace Settings (`/settings`, ADR 0022 SettingsScreen). */
export function Settings() {
  const me = useMe();

  if (me.status === 'loading') {
    return <Spin size="large" style={{ marginTop: 80 }} />;
  }
  if (me.status === 'error') {
    return (
      <PageError
        error={me.error}
        kind={me.kind}
        httpStatus={me.httpStatus}
        requestId={me.requestId}
      />
    );
  }
  if (!me.data.is_workspace_admin) {
    return <Forbidden message="Workspace settings are restricted to workspace admins." />;
  }

  return (
    <Page gap={16}>
      <Typography.Title level={3} style={{ margin: 0 }}>
        Settings
      </Typography.Title>
      <Tabs
        defaultActiveKey="general"
        items={[
          { key: 'general', label: 'General', children: <GeneralTab /> },
          { key: 'secrets', label: 'Secrets', children: <SecretsTab /> },
          { key: 'webhooks', label: 'Webhooks', children: <WebhooksTab /> },
          { key: 'notifications', label: 'Notifications', children: <NotificationsTab /> },
          { key: 'danger', label: 'Danger zone', children: <DangerTab /> },
        ]}
      />
    </Page>
  );
}

/**
 * Authentication readout + the SMTP pre-flight test (#737, ADR 0032 decision 7): "send me a test
 * mail" so a misconfigured email OTP mailer is caught at install time.
 */
function GeneralTab() {
  const { message } = App.useApp();
  const { run, loading } = useAsyncAction('SMTP pre-flight test failed');

  const onTestAuthEmail = () =>
    run(async () => {
      const { to } = await testAuthEmail();
      message.success(`Test email sent to ${to} — check your inbox.`);
    });

  return (
    <Card size="small">
      <Descriptions column={1} size="small">
        <Descriptions.Item label="Workspace">DataQ</Descriptions.Item>
        <Descriptions.Item label="Tenancy">
          <Tag>Single tenant</Tag>
        </Descriptions.Item>
        <Descriptions.Item label="Authentication">{authMethodLabel}</Descriptions.Item>
      </Descriptions>
      <Flex vertical gap={4} style={{ marginTop: 16 }}>
        <Button onClick={onTestAuthEmail} loading={loading} style={{ alignSelf: 'flex-start' }}>
          Send test email
        </Button>
        <Typography.Text type="secondary" style={{ fontSize: 12 }}>
          Sends a real message to your own address over the configured email sign-in mailer (
          <Typography.Text code>AUTH_EMAIL_*</Typography.Text>). If it doesn&apos;t arrive, the
          error names the transport stage that failed — connect, TLS, auth, or send.
        </Typography.Text>
      </Flex>
    </Card>
  );
}

function SecretsTab() {
  return (
    <Alert
      type="info"
      showIcon
      title="Credentials live in the secret store, never the database"
      description="Connection credentials and notification webhooks are written through the configured secret store (Azure Key Vault in production) and referenced only by key. There's nothing to edit here — secrets are rotated from the connection's Re-authenticate action."
    />
  );
}

function NotificationsTab() {
  return (
    <Alert
      type="info"
      showIcon
      title="Alerts are configured per suite"
      description={
        <span>
          Microsoft Teams alerts (webhook + fail / warn / always threshold) are set on each suite so
          the owning team is notified for their data. Open a suite from{' '}
          <Link to="/suites">Suites</Link> to configure its notifications. A workspace-wide default
          channel is a post-v1 follow-up.
        </span>
      }
    />
  );
}

function DangerTab() {
  return (
    <Alert
      type="warning"
      showIcon
      title="No destructive workspace actions in v1"
      description="Workspace-level danger-zone actions (transfer ownership, purge run history, delete workspace) aren't available yet. Per-entity delete lives on each connection / suite."
    />
  );
}

/**
 * Inbound orchestration-webhook URLs (#490) — one copy-paste target per orchestration provider
 * (ADF / Airflow / dbt) to notify DataQ on pipeline completion.
 */
function WebhooksTab() {
  const { state } = useAsyncData(listAdminWebhooks);
  return (
    <Card title="Inbound webhooks (orchestration)" size="small">
      <Flex vertical gap={12}>
        <Typography.Text type="secondary">
          Ready-to-paste URLs for an orchestrator to notify DataQ on pipeline/DAG completion. The
          ADF URL carries a shared secret in the query string — treat it as a credential.
        </Typography.Text>
        {state.status === 'loading' && <Spin size="large" />}
        {state.status === 'error' && (
          <Alert
            type="error"
            showIcon
            title="Failed to load webhook config"
            description={state.error}
          />
        )}
        {state.status === 'ok' && state.data.length === 0 && (
          <Typography.Text type="secondary">
            No orchestration connections configured.
          </Typography.Text>
        )}
        {state.status === 'ok' &&
          state.data.map((wh) => <WebhookRow key={wh.provider} webhook={wh} />)}
      </Flex>
    </Card>
  );
}

/** One provider's webhook URL. ADF embeds a secret, so it's masked behind a reveal
 *  toggle; copy always copies the real URL. */
function WebhookRow({ webhook }: { webhook: AdminWebhook }) {
  const [revealed, setRevealed] = useState(false);
  const secretBearing = webhook.provider === 'adf';
  // Mask only the token value, keeping the rest of the URL legible.
  const display =
    secretBearing && !revealed
      ? webhook.inbound_url.replace(/token=[^&]*/i, 'token=••••••••')
      : webhook.inbound_url;
  return (
    <Card
      size="small"
      type="inner"
      title={
        <Flex align="center" gap={8}>
          <Tag color={secretBearing ? 'geekblue' : 'cyan'}>{PROVIDER_LABELS[webhook.provider]}</Tag>
          {!webhook.token_configured && <Tag color="error">webhook secret not set</Tag>}
        </Flex>
      }
    >
      <Flex vertical gap={8}>
        <Flex align="center" gap={8}>
          <Input readOnly value={display} style={{ fontFamily: 'monospace' }} />
          {secretBearing && (
            <Button
              icon={revealed ? <EyeInvisibleOutlined /> : <EyeOutlined />}
              onClick={() => setRevealed((r) => !r)}
              title={revealed ? 'Hide token' : 'Reveal token'}
            />
          )}
          <Typography.Text copyable={{ text: webhook.inbound_url }} />
        </Flex>
        <Typography.Text type="secondary" style={{ fontSize: 12 }}>
          {webhook.auth}
        </Typography.Text>
        {secretBearing ? (
          <Typography.Text type="secondary" style={{ fontSize: 12 }}>
            Paste into Azure Monitor → Action Group → Webhook. Live delivery also needs the
            Common-Alert-Schema payload mapping (#492).
          </Typography.Text>
        ) : (
          <Typography.Text type="secondary" style={{ fontSize: 12 }}>
            Configured in the {PROVIDER_CALLBACK_NOUNS[webhook.provider]} callback snippet (HMAC);
            signing key in the secret store:{' '}
            <Typography.Text code>{webhook.signing_secret_name}</Typography.Text>.
          </Typography.Text>
        )}
        <Flex gap={4} wrap align="center">
          <Typography.Text type="secondary" style={{ fontSize: 12 }}>
            Connections:
          </Typography.Text>
          {webhook.connection_names.map((name) => (
            <Tag key={name}>{name}</Tag>
          ))}
        </Flex>
      </Flex>
    </Card>
  );
}

